#!/bin/bash
# Владелец файла — разработчик CI (MEE-166).
#
# Выносит вердикт шага аннотацией работы. Довод тот же, что у шага SwiftLint:
# «шаг отработал» должно подтверждаться, не открывая журнал работы. При отказе
# в аннотацию уходит хвост журнала — иначе причина отказа видна только тому, у
# кого есть доступ к хранилищу логов Actions, а у читателя PR его может не быть.
set -o pipefail
title="$1"
status="$2"
log="$3"

# Перевод строки в аннотации кодируется %0A, сам знак процента — %25.
encode() {
  awk '{ gsub(/%/, "%25"); printf "%s%%0A", $0 }' | cut -c1-4000
}

if [ "$status" -ne 0 ]; then
  printf '::error title=%s::шаг завершился с кодом %s. Хвост журнала:%%0A%s\n' \
    "$title" "$status" "$(tail -n 40 "$log" | encode)"
else
  verdict=$(grep -m1 -e '^Таргетов с графом' -e '^Граф пуст' "$log" || echo 'вердикт в журнале шага')
  printf '::notice title=%s::%s Нарушений нет.\n' "$title" "$verdict"
fi
